package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.StudyPublicEvidence.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.jlinalg.study.StudyOperationExecutor.Context;
import org.jlinalg.study.StudyOperationExecutor.State;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StudyRareCohortOverlapTest {
    @TempDir Path root;
    private void seal(Path directory,String type,String state,Map<String,Object> details)throws Exception {
        var hashes=new LinkedHashMap<String,Object>();try(var paths=Files.walk(directory)){for(Path p:paths.filter(Files::isRegularFile).filter(p->!p.getFileName().toString().equals("manifest.yaml")).toList())hashes.put(directory.relativize(p).toString().replace('\\','/'),FollowupSupport.hash(p));}
        write(directory.resolve("manifest.yaml"),Map.of("operation_id",directory.getFileName().toString(),"operation_type",type,"hypothesis","H","state",state,"output_sha256",hashes,"details",details));
    }
    private Context context(String name,Map<String,Object> analysis,Path source)throws Exception {
        var datasets=List.of(Map.of("id","A","cohort","cohort-A","type","gwas"),Map.of("id","B","cohort","cohort-B","type","gwas"),Map.of("id","C","cohort","cohort-C","type","gwas"));var roles=Map.of("discovery",List.of("A"),"replication",List.of("B","C"));var op=Map.<String,Object>of("id",name,"type","rare_cohort_overlap","hypothesis","H","datasets",List.of("A","B","C"),"roles",roles);return new Context(root,Files.createDirectories(root.resolve(name)),op,Map.of("datasets",datasets,"hypotheses",List.of(Map.of("id","H","inputs",roles,"analysis",analysis))),Map.of(),Map.of("rare",source));
    }
    private Path source(String name,boolean signed,boolean missing,String state)throws Exception {
        Path directory=Files.createDirectories(root.resolve(name));var output=new ArrayList<String[]>();var families=new ArrayList<Object>();String primary=signed?"burden":"acat-o";
        for(String scope:List.of("cohort:A","cohort:B","cohort:C","discovery","primary")){
            var probabilities=new LinkedHashMap<String,Double>();var scopeRows=new ArrayList<String[]>();
            for(String feature:List.of("f1","f2","f3"))for(String mask:List.of("lof","missense"))for(String test:List.of(primary,"skat")){
                boolean selected=test.equals(primary)&&(feature.equals("f1")&&mask.equals("lof")&&!scope.equals("cohort:C")||feature.equals("f2")&&mask.equals("missense")&&(scope.equals("cohort:A")||scope.equals("discovery")||scope.equals("primary"))||feature.equals("f3")&&mask.equals("lof")&&scope.equals("cohort:C"))||test.equals("skat")&&feature.equals("f2")&&mask.equals("lof");
                boolean absent=missing&&scope.equals("cohort:C")&&feature.equals("f2")&&mask.equals("lof")&&test.equals(primary);double probability=selected?.00001:.9;String key=feature+":"+mask+":"+test;if(!absent)probabilities.put(key,probability);
                scopeRows.add(new String[]{scope,feature,mask,test,signed&&test.equals(primary)?"signed_burden":"unsigned_set",absent?"not_eligible":"ok",absent?"NA":String.valueOf(probability),"NA",signed&&test.equals(primary)?scope.equals("cohort:B")?"-1":"1":"NA","false"});
            }
            var adjusted=StudyCohortResults.adjust(probabilities,"BY");for(String[] row:scopeRows){row[7]=String.valueOf(adjusted.getOrDefault(row[1]+":"+row[2]+":"+row[3],Double.NaN));output.add(row);}families.add(Map.of("scope",scope,"complete",!scope.equals("primary")||state.equals("complete"),"testing_denominator",probabilities.size(),"adjustment","BY"));
        }
        FollowupSupport.table(directory.resolve("rare-results.tsv"),List.of("scope","feature_id","mask_id","test","result_type","status","p_value","adjusted_p","beta","is_primary_test"),output);
        seal(directory,"rare_variant_analysis",state,Map.of("families",families,"primary_identity",Map.of("test",primary),"method_report",Map.of("parameters",Map.of("multiple_testing","BY","discovery",List.of("A"))),"incomplete_scopes",state.equals("complete")?List.of():List.of("primary")));return directory;
    }
    private static List<Map<String,String>> rows(Path file)throws Exception {var table=DelimitedData.readResult(file);var out=new ArrayList<Map<String,String>>();for(String[] row:table.rows()){var record=new LinkedHashMap<String,String>();for(int i=0;i<row.length;i++)record.put(table.header().get(i),row[i]);out.add(record);}return out;}
    private void update(Path source,java.util.function.Consumer<Map<String,Object>> change)throws Exception {var m=StudyYaml.loadArtifact(source.resolve("manifest.yaml"));var details=map(m.get("details"));change.accept(details);seal(source,"rare_variant_analysis",text(m.get("state")),details);}
    @Test void exactMaskTestPatternsPreserveJointSourceFdrAndUnsignedDirections()throws Exception {
        var c=context("exact",Map.of(),source("source",false,false,"complete"));var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals("set_mask_prespecified_test",result.details().get("counting_unit"));assertEquals(false,result.details().get("primary_cohort_set_changed"));
        var membership=rows(c.outputDirectory().resolve("cohort-overlap-membership.tsv"));assertEquals(18,membership.size());assertTrue(membership.stream().allMatch(r->r.get("test").equals("acat-o")&&r.get("beta").equals("NA")&&r.get("same_sign_reference").equals("unavailable")&&r.get("source_testing_denominator").equals("12")&&r.get("adjusted_p").equals(r.get("source_adjusted_p"))));
        var patterns=rows(c.outputDirectory().resolve("cohort-overlap-patterns.tsv"));for(String pattern:List.of("100","110","001"))assertEquals("1",patterns.stream().filter(r->r.get("selected_pattern").equals(pattern)).findFirst().orElseThrow().get("features"));assertEquals("3",patterns.stream().filter(r->r.get("selected_pattern").equals("000")).findFirst().orElseThrow().get("features"));
        assertTrue(list(result.details().get("zero_overlap_alerts")).stream().map(StudyPublicEvidence::map).anyMatch(a->a.get("dataset").equals("C")&&Boolean.TRUE.equals(a.get("alert"))));assertTrue(Files.size(c.outputDirectory().resolve("cohort-overlap-venn.pdf"))>1000);assertTrue(Files.size(c.outputDirectory().resolve("cohort-overlap-upset.png"))>1000);
        seal(c.outputDirectory(),"rare_cohort_overlap","complete",result.details());var op=Map.<String,Object>of("id","inventory","type","finding_inventory");var inventory=new Context(root,Files.createDirectories(root.resolve("inventory")),op,c.study(),Map.of(),Map.of("overlap",c.outputDirectory()));assertEquals(State.COMPLETE,new StudyCliExecutor().execute(inventory).state());String dossier=Files.readString(inventory.outputDirectory().resolve("finding-inventory.jsonl"));assertTrue(dossier.contains("rare_cohort_overlap_context"));assertTrue(dossier.contains("source_testing_denominator"));for(String line:dossier.lines().toList())assertEquals(false,map(StudyYaml.load(line)).get("candidate"));
    }
    @Test void unionRetainsUnobservedRowsAndIntersectionDoesNotCallThemNegative()throws Exception {
        var source=source("partial-coverage",false,true,"complete");for(String universe:List.of("intersection","union")){var c=context(universe,Map.of("cohort_overlap",Map.of("universe",universe)),source);var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals(universe.equals("intersection")?5:6,((Number)result.details().get("universe_features")).intValue());var row=rows(c.outputDirectory().resolve("cohort-overlap-membership.tsv")).stream().filter(r->r.get("feature_id").equals("f2")&&r.get("mask_id").equals("lof")&&r.get("set_id").equals("C")).findFirst().orElseThrow();assertEquals("false",row.get("source_estimable"));assertEquals("NA",row.get("adjusted_p"));assertEquals(universe.equals("intersection")?"outside_overlap_universe":"not_estimable_or_unobserved",row.get("status"));}
    }
    @Test void completeCohortsRemainUsableWhenPrimaryIsWaitingButOneIncompleteCohortBlocksScope()throws Exception {
        var source=source("waiting",false,false,"waiting_for_input");var c=context("cohorts-complete",Map.of(),source);assertEquals(State.COMPLETE,new StudyCliExecutor().execute(c).state());update(source,d->{var families=new ArrayList<Object>();for(Object raw:list(d.get("families"))){var f=map(raw);if(f.get("scope").equals("cohort:C"))f.put("complete",false);families.add(f);}d.put("families",families);});var blocked=context("cohort-incomplete",Map.of(),source);assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(blocked).state());assertFalse(Files.exists(blocked.outputDirectory().resolve("cohort-overlap-membership.tsv")));
    }
    @Test void secondaryTestAdjustmentAndFullScopeCannotBeDiscarded()throws Exception {
        var source=source("secondary",false,false,"complete");String raw=Files.readString(source.resolve("rare-results.tsv"));Files.writeString(source.resolve("rare-results.tsv"),raw.replaceFirst("(cohort:A\\tf1\\tlof\\tskat\\tunsigned_set\\tok\\t0.9\\t)[^\\t]+","$1NA"));update(source,d->{});var c=context("secondary-missing",Map.of(),source);assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(c).state());assertFalse(Files.exists(c.outputDirectory().resolve("cohort-overlap-patterns.tsv")));
        var other=source("tampered",false,false,"complete");Files.writeString(other.resolve("rare-results.tsv"),Files.readString(other.resolve("rare-results.tsv"))+"\n");assertThrows(IOException.class,()->new StudyCliExecutor().execute(context("tamper-reject",Map.of(),other)));
    }
    @Test void reducedValidationCorrectsEveryFrozenTestAndRetainsSourceDenominator()throws Exception {
        var c=context("reduced",Map.of("cohort_overlap",Map.of("validation_family","discovery_subset")),source("reduced-source",false,false,"complete"));var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals(3,((Number)result.details().get("frozen_discovery_tests")).intValue());var families=rows(c.outputDirectory().resolve("cohort-overlap-families.tsv"));for(var row:families)assertEquals(row.get("set_id").equals("A")?"12":"3",row.get("selection_testing_denominator"));var row=rows(c.outputDirectory().resolve("cohort-overlap-membership.tsv")).stream().filter(r->r.get("set_id").equals("B")&&r.get("feature_id").equals("f1")&&r.get("mask_id").equals("lof")).findFirst().orElseThrow();double expected=.00001*3*(1+1.0/2+1.0/3)/2;assertEquals(expected,Double.parseDouble(row.get("adjusted_p")),1e-12);assertNotEquals(row.get("source_adjusted_p"),row.get("adjusted_p"));assertEquals("12",row.get("source_testing_denominator"));
    }
    @Test void unsignedDirectionCannotMasqueradeAsNegativeValidationAndSignedEffectsKeepOpposition()throws Exception {
        var unsigned=context("unsigned-direction",Map.of("cohort_overlap",Map.of("direction","require_discovery")),source("unsigned",false,false,"complete"));assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(unsigned).state());
        var source=source("signed",true,false,"complete");var report=context("signed-report",Map.of(),source);assertEquals(State.COMPLETE,new StudyCliExecutor().execute(report).state());assertTrue(rows(report.outputDirectory().resolve("cohort-overlap-features.tsv")).stream().anyMatch(r->r.get("direction_context").equals("opposite_selected_burden_directions")));var required=context("signed-filter",Map.of("cohort_overlap",Map.of("direction","require_discovery")),source);assertEquals(State.COMPLETE,new StudyCliExecutor().execute(required).state());assertTrue(rows(required.outputDirectory().resolve("cohort-overlap-membership.tsv")).stream().filter(r->r.get("set_id").equals("B")).noneMatch(r->r.get("selected").equals("true")));
    }
    @Test void unknownDiscoveryCompositionAndWorkBoundsWithholdCompleteViews()throws Exception {
        var source=source("composition",false,false,"complete");var c=context("bad-discovery",Map.of(),source);var op=new LinkedHashMap<>(c.operation());op.put("roles",Map.of("discovery",List.of("A","B"),"replication",List.of("C")));var multiple=new Context(c.project(),c.outputDirectory(),op,c.study(),c.plan(),c.dependencyDirectories());assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(multiple).state());for(var policy:List.of(Map.of("maximum_features",1),Map.of("maximum_sets",2),Map.of("maximum_cells",1))){var limited=context("limit-"+policy.keySet().iterator().next(),Map.of("cohort_overlap",policy),source);assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(limited).state());assertFalse(Files.exists(limited.outputDirectory().resolve("cohort-overlap-membership.tsv")));}
    }
    private Context supplied(String name,Path source)throws Exception {
        var definition=Map.of("id","provided","kind","rare_cohort_overlap","files",Map.of("results",root.relativize(source).toString()),"scope",Map.of("datasets",List.of("A","B","C")),"method",Map.of("name","External rare membership and selection"));var c=context(name,Map.of("supplied_results",List.of(definition)),source.getParent());var op=new LinkedHashMap<>(c.operation());op.put("supplied_result_id","provided");return new Context(c.project(),c.outputDirectory(),op,c.study(),c.plan(),Map.of());
    }
    @Test void incompleteDiscoveryPoolOnlyBlocksOperationsThatNeedItsReference()throws Exception {
        var source=source("incomplete-pool",false,false,"waiting_for_input");update(source,d->{d.put("method_report",Map.of("parameters",Map.of("multiple_testing","BY","discovery",List.of("A","B"))));var families=new ArrayList<Object>();for(Object raw:list(d.get("families"))){var f=map(raw);if(f.get("scope").equals("discovery"))f.put("complete",false);families.add(f);}d.put("families",families);});
        for(boolean reduced:List.of(false,true)){var c=context("optional-discovery-"+reduced,Map.of("cohort_overlap",Map.of("validation_family",reduced?"discovery_subset":"all_results")),source);var op=new LinkedHashMap<>(c.operation());op.put("roles",Map.of("discovery",List.of("A","B"),"replication",List.of("C")));c=new Context(c.project(),c.outputDirectory(),op,c.study(),c.plan(),c.dependencyDirectories());var result=new StudyCliExecutor().execute(c);assertEquals(reduced?State.WAITING_FOR_INPUT:State.COMPLETE,result.state(),result.summary());if(!reduced)assertTrue(result.details().containsKey("discovery_reference_status"));}
    }
    @Test void nativeDeclaredEmptyAnalysisIsInapplicableButAnEmptyExternalExportIsNotNegativeEvidence()throws Exception {
        var source=source("empty-native",false,false,"complete");Path file=source.resolve("rare-results.tsv");Files.writeString(file,Files.readString(file).lines().findFirst().orElseThrow()+"\n");update(source,d->{d.put("families",List.of());d.put("result_rows",0);d.put("primary_estimable_tests",0);d.put("evidence_disposition","not_estimable");var method=map(d.get("method_report"));method.put("performed",false);d.put("method_report",method);});var c=context("empty-native-view",Map.of(),source);var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals(false,map(result.details().get("method_report")).get("performed"));assertEquals(true,result.details().get("source_declared_zero_eligible_tests"));assertFalse(Files.exists(c.outputDirectory().resolve("cohort-overlap-membership.tsv")));update(source,d->d.put("execution_origin","externally_produced"));var external=context("empty-external-view",Map.of(),source);assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(external).state());
    }
    @Test void suppliedRareMembershipRetainsMasksAndOnlyBuildsMissingViews()throws Exception {
        var c=context("native-export",Map.of(),source("external-source",false,false,"complete"));assertEquals(State.COMPLETE,new StudyCliExecutor().execute(c).state());Path exported=c.outputDirectory().resolve("cohort-overlap-membership.tsv");var reused=supplied("reuse",exported);var result=new StudyCliExecutor().execute(reused);assertEquals(State.COMPLETE,result.state(),result.summary());assertEquals(false,result.details().get("analysis_executed_by_jlinalg"));assertEquals(18,rows(reused.outputDirectory().resolve("cohort-overlap-membership.tsv")).size());assertEquals(6,rows(reused.outputDirectory().resolve("cohort-overlap-features.tsv")).size());assertTrue(rows(reused.outputDirectory().resolve("cohort-overlap-features.tsv")).stream().allMatch(r->Set.of("lof","missense").contains(r.get("mask_id"))));assertTrue(Files.size(reused.outputDirectory().resolve("cohort-overlap-upset.pdf"))>1000);assertEquals(false,StudyYaml.loadArtifact(reused.outputDirectory().resolve("cohort-overlap.yaml")).get("alert_assessment_complete"));
        String data=Files.readString(exported);Files.writeString(root.resolve("missing.tsv"),data.substring(0,data.lastIndexOf('\n',data.length()-2)+1));var missing=supplied("missing-import",root.resolve("missing.tsv"));assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(missing).state());assertFalse(Files.exists(missing.outputDirectory().resolve("cohort-overlap-upset.png")));
        Files.writeString(root.resolve("duplicate.tsv"),data+data.split("\n")[1]+"\n");assertThrows(IOException.class,()->new StudyCliExecutor().execute(supplied("duplicate-import",root.resolve("duplicate.tsv"))));
    }
}
